import "core-js/modules/es.array.push.js";
/* eslint-disable */
import { edit_or_delete_dashboard_topic } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
// import { update_audit_logs } from "@/mixins/AuditLogActions.js";
export default {
  props: {
    SortVisibility: Boolean,
    rowInfo: Object,
    access_type: String
  },
  // mixins: [update_audit_logs],
  data() {
    return {
      max: 999,
      min: 1,
      servicecharge: [],
      sort_number: 1,
      loading: false,
      toggle_exclusive: "",
      number_rules: [v => /^[0-9]{1,3}$/.test(v) || " Number must be valid"]
    };
  },
  watch: {
    SortVisibility: {
      async handler() {
        if (this.SortVisibility == true) {
          this.sort_number = this.rowInfo.sort_range == undefined ? 1 : this.rowInfo.sort_range;
          this.toggle_exclusive = this.rowInfo.is_visible == true ? "enabel_dahboard" : "disabel_dahboard";
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async validate_data() {
      // if (this.$refs.form.validate()) {
      let app_details = [];
      if (this.rowInfo.dashboard_id) {
        app_details.push({
          dashboard_id: this.rowInfo.dashboard_id,
          is_visible: this.rowInfo.is_visible == true ? false : true
        });
      }
      if (this.rowInfo.admin_dashboard_id) {
        app_details.push({
          dashboard_id: this.rowInfo.admin_dashboard_id,
          is_visible: this.rowInfo.is_visible ? this.rowInfo.is_visible == true ? false : true : this.rowInfo.admin_is_visible == true ? false : true
        });
      }
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(edit_or_delete_dashboard_topic, {
          input: {
            app_details: JSON.stringify(app_details),
            action_type: "EDIT",
            dashboard_id: this.access_type == "user" ? this.rowInfo.dashboard_id : this.rowInfo.admin_dashboard_id,
            organization_id: data.organization.organization_id,
            is_visible: this.access_type == "user" ? this.rowInfo.is_visible == true ? false : true : this.access_type == "admin" ? this.rowInfo.admin_is_visible == true ? false : true : false
            // sort_range: parseInt(this.sort_number),
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.edit_or_delete_dashboard_topic);
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          // this.fetch_audit_message();
          // this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    },
    async fetch_audit_message() {
      var datas = this.$store.getters.GetUserObj;
      var data = {
        AuditType: "WEB_ACTION",
        AuditAction: "APP_VISIBILTY",
        AuditMessage: ` ${datas.user.full_user_name}   ${this.rowInfo.is_visible == true ? "Disabled" : "Enabled"} ${this.rowInfo.dashboard_name}  App  `
      };
      this.$store.commit("SetAuditActions", data);
      // this.update_audit_logs();
    }
  }
  // },
};
